// Non-Contiguous Cartogram — Geo, route: jsx
// Source: non-contiguous-cartogram
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react, topojson-client, topojson-specification, us-atlas, world-atlas.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { feature, mesh } from 'topojson-client';
import countries110m from 'world-atlas/countries-110m.json';
import statesUs from 'us-atlas/states-10m.json';
import type { GeometryCollection, Topology } from 'topojson-specification';
import type { Feature, FeatureCollection, Geometry, MultiLineString } from 'geojson';
import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from geo ----
// The atlases ship untyped JSON. One cast per topology at this boundary keeps every
// consumer strict, and converting here means each chart does not re-derive the same
// geometry at module load.

type Named = { name: string };
type NamedFeature = Feature<Geometry, Named>;

const world = countries110m as unknown as Topology<{
  countries: GeometryCollection<Named>;
  land: GeometryCollection;
}>;

const us = statesUs as unknown as Topology<{
  states: GeometryCollection<Named>;
  nation: GeometryCollection;
}>;

const worldCountries = feature(
  world,
  world.objects.countries
) as FeatureCollection<Geometry, Named>;

const worldLand = feature(world, world.objects.land) as FeatureCollection<Geometry>;

/** Shared borders only, so neighbouring outlines are stroked once instead of twice. */
const worldBorders = mesh(
  world,
  world.objects.countries,
  (a, b) => a !== b
) as MultiLineString;

const usNation = feature(us, us.objects.nation) as FeatureCollection<Geometry>;

const usStateBorders = mesh(
  us,
  us.objects.states,
  (a, b) => a !== b
) as MultiLineString;

/**
 * The 50 states plus DC. geoAlbersUsa cannot project FIPS ids of 60 and above
 * (territories) and returns null for them, which becomes a NaN centroid downstream.
 * Use this rather than the raw collection for anything Albers-projected.
 */
const usStates: NamedFeature[] = (
  feature(us, us.objects.states) as FeatureCollection<Geometry, Named>
).features.filter((d) => Number(d.id) < 60);

const usStatesCollection: FeatureCollection<Geometry, Named> = {
  type: 'FeatureCollection',
  features: usStates
};

/**
 * FNV-1a over an id, run through the murmur3 finalizer. Two-character FIPS ids barely
 * differ, and without the finalizer they map to a near-constant. Returns [0, 1).
 * Charts use it to synthesize per-region values deterministically instead of fetching.
 */
function hashUnit(id: string, salt = 0): number {
  let h = 2166136261 ^ salt;
  for (let i = 0; i < id.length; i++) {
    h = Math.imul(h ^ id.charCodeAt(i), 16777619);
  }
  h ^= h >>> 16;
  h = Math.imul(h, 2246822507);
  h ^= h >>> 13;
  return (h >>> 0) / 4294967296;
}

const MARGIN = { top: 12, right: 12, bottom: 46, left: 12 };
const LEGEND_WIDTH = 180;
const LEGEND_HEIGHT = 10;

/** Seeded stand-in for the CDC obesity rates the source notebook loaded: FNV-1a over the FIPS id. */
function syntheticRate(id: string): number {
  let hash = 2166136261;
  for (let i = 0; i < id.length; i++) hash = Math.imul(hash ^ id.charCodeAt(i), 16777619);
  return 0.21 + ((hash >>> 0) % 1000) / 1000 * 0.19;
}

function stateName(f: Feature<Geometry>): string {
  return (f.properties as { name?: string } | null)?.name ?? 'Unknown';
}

const formatRate = d3.format('.1%');

/** One value per region, keyed by its FIPS id. A region with no entry is drawn at zero. */
export type Data = Record<string, number>;

const DEMO: Data = Object.fromEntries(
  usStatesCollection.features.map((f) => [String(f.id ?? ''), syntheticRate(String(f.id ?? ''))])
);

export default function NonContiguousCartogram({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.68);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const { borderPath, states, color } = useMemo(() => {
    const projection = d3
      .geoAlbersUsa()
      .fitSize([Math.max(innerWidth, 1), Math.max(innerHeight, 1)], usStatesCollection);
    const path = d3.geoPath(projection);

    // geoAlbersUsa drops Puerto Rico, leaving an empty path and a NaN centroid.
    const states = usStatesCollection.features
      .map((f) => {
        const id = String(f.id ?? '');
        const [cx, cy] = path.centroid(f);
        return { id, name: stateName(f), d: path(f) ?? '', cx, cy, rate: data[id] ?? 0 };
      })
      .filter((s) => s.d !== '' && Number.isFinite(s.cx) && Number.isFinite(s.cy));

    const [lo, hi] = d3.extent(states, (s) => s.rate) as [number, number];
    const color = d3.scaleSequential(d3.nice(lo, hi, 5), (t) =>
      d3.interpolateYlOrRd(0.25 + t * 0.7)
    );

    return { borderPath: path(usStateBorders) ?? '', states, color };
  }, [data, innerWidth, innerHeight]);

  const legendTicks = useMemo(() => {
    const [lo, hi] = color.domain();
    return d3
      .ticks(lo, hi, 4)
      .map((v) => ({ value: formatRate(v), offset: ((v - lo) / (hi - lo)) * LEGEND_WIDTH }));
  }, [color]);

  const legendStops = useMemo(() => {
    const [lo, hi] = color.domain();
    return d3.range(0, 1.0001, 0.05).map((t) => ({ t, stop: color(lo + t * (hi - lo)) }));
  }, [color]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Non-contiguous cartogram of US states scaled about their centroids by adult obesity rate"
    >
      <defs>
        <linearGradient id="cartogram-legend" x1="0%" x2="100%">
          {legendStops.map((s) => (
            <stop key={s.t} offset={`${s.t * 100}%`} stopColor={s.stop} />
          ))}
        </linearGradient>
      </defs>

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`} strokeLinejoin="round">
        <path d={borderPath} fill="none" stroke="var(--line)" strokeWidth={1} />
        {states.map((s) => (
          <path
            key={s.id}
            d={s.d}
            /* Shrink each state in place about its own centroid: area encodes the rate. */
            transform={`translate(${s.cx},${s.cy}) scale(${Math.sqrt(s.rate)}) translate(${-s.cx},${-s.cy})`}
            fill={color(s.rate)}
            stroke="var(--bg)"
            strokeWidth={0.75}
            vectorEffect="non-scaling-stroke"
          >
            <title>{`${s.name}\n${formatRate(s.rate)}`}</title>
          </path>
        ))}
      </g>

      <g transform={`translate(${MARGIN.left + 24},${height - MARGIN.bottom + 16})`}>
        <rect width={LEGEND_WIDTH} height={LEGEND_HEIGHT} fill="url(#cartogram-legend)" />
        {legendTicks.map((t) => (
          <text
            key={t.value}
            x={t.offset}
            y={LEGEND_HEIGHT + 12}
            textAnchor="middle"
            fill="var(--muted)"
            fontSize={10}
          >
            {t.value}
          </text>
        ))}
        <text x={0} y={-4} fill="var(--muted)" fontSize={11}>
          Adult obesity (self-reported)
        </text>
      </g>
    </svg>
  );
}
